// The bundled map. Everything it draws comes from /map/*.json, which is generated by tooling/build-map.mjs
// and only changes when the site is redeployed. Nothing here talks to a map provider.
const NS = 'http://www.w3.org/2000/svg';
let basePromise;
const tileCache = new Map();

function unpack(flat) {
  const points = [];
  let x = 0;
  let y = 0;
  for (let i = 0; i < flat.length; i += 2) {
    x = i ? x+flat[i] : flat[i];
    y = i ? y+flat[i+1] : flat[i+1];
    points.push([x,y]);
  }
  return points;
}
const path = (points,close) => 'M'+points.map((p)=>p[0]+' '+p[1]).join('L')+(close?'Z':'');
function load() {
  basePromise ??= fetch('/map/base.json').then((response)=>{
    if (!response.ok) throw new Error('The map could not be loaded.');
    return response.json();
  }).then((base)=>{
    for (const area of base.areas) {
      area.points = area.rings.map(unpack);
      const xs = area.points.flat().map((p)=>p[0]);
      area.width = Math.max(...xs)-Math.min(...xs);
    }
    return base;
  }).catch((error)=>{ basePromise = null; throw error; });
  return basePromise;
}
function contains(area,[x,y]) {
  let hit = false;
  for (const ring of area.points) for (let i = 0, j = ring.length-1; i < ring.length; j = i++) {
    const [xi,yi] = ring[i];
    const [xj,yj] = ring[j];
    if ((yi > y) !== (yj > y) && x < (xj-xi)*(y-yi)/(yj-yi)+xi) hit = !hit;
  }
  return hit;
}
function node(name,attrs = {},parent) {
  const element = document.createElementNS(NS,name);
  for (const [key,value] of Object.entries(attrs)) element.setAttribute(key,value);
  parent?.append(element);
  return element;
}

// options: home (area id), selected (area id), pin (allow dropping a pin), onPick(area, point)
export async function mount(root,options = {}) {
  const base = await load();
  if (!root.isConnected) return null;
  const [minX,minY,maxX,maxY] = base.box;
  const full = { x:minX,y:minY,w:maxX-minX,h:maxY-minY };
  const home = base.areas.find((area)=>area.id===options.home);
  const near = new Set(home?.near ?? []);
  let selected = options.selected ?? '';
  let view = { ...full };

  root.textContent = '';
  root.classList.add('map');
  const svg = node('svg',{ role:'img','aria-label':'Map of Cleveland neighborhoods and surrounding suburbs',preserveAspectRatio:'xMidYMid meet' },root);
  node('rect',{ x:minX-20000,y:minY-20000,width:full.w+40000,height:full.h+40000,class:'map-ground' },svg);
  const shapes = node('g',{ class:'map-areas' },svg);
  const byId = new Map();
  for (const area of base.areas) {
    const shape = node('path',{ d:area.points.map((ring)=>path(ring,true)).join(''),'data-area':area.id,'fill-rule':'evenodd',
      class:'map-area'+(area.region==='Cleveland'?' city':'')+(area.id===options.home?' home':near.has(area.id)?' near':'') },shapes);
    node('title',{},shape).textContent = area.name;
    byId.set(area.id,shape);
  }
  node('path',{ d:base.water.map((ring)=>path(unpack(ring),true)).join(''),class:'map-water' },svg);
  const streets = node('g',{ class:'map-streets' },svg);
  node('path',{ d:base.roads[2].map((line)=>path(unpack(line))).join(''),class:'map-road' },svg);
  node('path',{ d:base.roads[1].map((line)=>path(unpack(line))).join(''),class:'map-highway-edge' },svg);
  node('path',{ d:base.roads[1].map((line)=>path(unpack(line))).join(''),class:'map-highway' },svg);
  const outline = node('path',{ class:'map-selected' },svg);
  const labels = node('g',{ class:'map-labels' },svg);
  const texts = base.areas.map((area)=>{
    const text = node('text',{ x:area.c[0],y:area.c[1],'text-anchor':'middle','dominant-baseline':'middle',class:area.id===options.home?'home':'' },labels);
    text.textContent = area.name;
    return [area,text];
  });
  const pin = node('g',{ class:'map-pin',hidden:'' },svg);
  node('path',{ d:'M0 0C-7-10-11-15-11-21a11 11 0 0 1 22 0c0 6-4 11-11 21z' },pin);
  node('circle',{ cx:0,cy:-21,r:4 },pin);

  const controls = document.createElement('div');
  controls.className = 'map-controls';
  controls.innerHTML = '<button type="button" data-zoom="in" aria-label="Zoom in">+</button><button type="button" data-zoom="out" aria-label="Zoom out">−</button>'+
    '<button type="button" data-zoom="home" aria-label="Show the whole map">⤢</button>';
  root.append(controls);
  const credit = document.createElement('p');
  credit.className = 'map-credit';
  credit.textContent = 'Map data: '+base.sources+'. Updated '+base.version+'.';
  root.append(credit);

  let pinPoint = null;
  const unitsPerPixel = () => Math.max(view.w/svg.clientWidth,view.h/svg.clientHeight) || 1;
  function showTiles(scale) {
    streets.toggleAttribute('hidden',scale > 14);
    if (scale > 14) return;
    const from = [Math.floor((view.x-minX)/base.tile)-1,Math.floor((view.y-minY)/base.tile)-1];
    const to = [Math.floor((view.x+view.w-minX)/base.tile)+1,Math.floor((view.y+view.h-minY)/base.tile)+1];
    for (let i = from[0]; i <= to[0]; i++) for (let j = from[1]; j <= to[1]; j++) {
      const key = i+'_'+j;
      if (!base.tiles.includes(key) || streets.querySelector('[data-tile="'+key+'"]')) continue;
      const slot = node('path',{ 'data-tile':key,class:'map-street' },streets);
      if (!tileCache.has(key)) tileCache.set(key,fetch('/map/t/'+key+'.json').then((r)=>r.ok ? r.json() : []).catch(()=>[]));
      tileCache.get(key).then((list)=>slot.setAttribute('d',list.map((line)=>path(unpack(line))).join('')));
    }
  }
  function draw() {
    const ratio = svg.clientWidth && svg.clientHeight ? svg.clientWidth/svg.clientHeight : full.w/full.h;
    view.w = Math.min(Math.max(view.w,900),Math.max(full.w,full.h*ratio));
    view.h = view.w/ratio;
    view.x = Math.min(Math.max(view.x,minX-view.w/2),maxX-view.w/2);
    view.y = Math.min(Math.max(view.y,minY-view.h/2),maxY-view.h/2);
    svg.setAttribute('viewBox',[view.x,view.y,view.w,view.h].join(' '));
    const scale = unitsPerPixel();
    labels.setAttribute('font-size',String(12*scale));
    for (const [area,text] of texts) {
      const fits = area.width/scale > area.name.length*6.4+8;
      text.toggleAttribute('hidden',!(fits || area.id===selected || (area.id===options.home && area.width/scale > 34)));
    }
    if (pinPoint) pin.setAttribute('transform','translate('+pinPoint[0]+' '+pinPoint[1]+') scale('+scale+')');
    showTiles(scale);
  }
  function zoom(factor,cx = view.x+view.w/2,cy = view.y+view.h/2) {
    const width = Math.min(Math.max(view.w*factor,900),full.w*1.6);
    const applied = width/view.w;
    view = { x:cx-(cx-view.x)*applied,y:cy-(cy-view.y)*applied,w:width,h:view.h*applied };
    draw();
  }
  function toMap(clientX,clientY) {
    const point = new DOMPoint(clientX,clientY).matrixTransform(svg.getScreenCTM().inverse());
    return [point.x,point.y];
  }
  function select(id,point) {
    selected = id ?? '';
    for (const [key,shape] of byId) shape.classList.toggle('chosen',key===selected);
    const area = base.areas.find((entry)=>entry.id===selected);
    outline.setAttribute('d',area ? area.points.map((ring)=>path(ring,true)).join('') : '');
    if (options.pin && point) {
      pinPoint = area ? point : null;
      pin.toggleAttribute('hidden',!pinPoint);
    }
    draw();
    return area;
  }
  function focus(id) {
    const area = base.areas.find((entry)=>entry.id===id);
    if (!area) return;
    const all = area.points.flat();
    const xs = all.map((p)=>p[0]);
    const ys = all.map((p)=>p[1]);
    const span = Math.max(Math.max(...xs)-Math.min(...xs),Math.max(...ys)-Math.min(...ys))*3.2;
    view = { x:(Math.min(...xs)+Math.max(...xs))/2-span/2,y:(Math.min(...ys)+Math.max(...ys))/2-span/2,w:span,h:span };
    draw();
  }

  const pointers = new Map();
  let moved = 0;
  let pinch = 0;
  svg.addEventListener('pointerdown',(event)=>{
    svg.setPointerCapture(event.pointerId);
    pointers.set(event.pointerId,[event.clientX,event.clientY]);
    if (pointers.size === 1) moved = 0;
    if (pointers.size === 2) { const [a,b] = [...pointers.values()]; pinch = Math.hypot(a[0]-b[0],a[1]-b[1]); }
  });
  svg.addEventListener('pointermove',(event)=>{
    const last = pointers.get(event.pointerId);
    if (!last) return;
    const scale = unitsPerPixel();
    pointers.set(event.pointerId,[event.clientX,event.clientY]);
    if (pointers.size === 1) {
      moved += Math.abs(event.clientX-last[0])+Math.abs(event.clientY-last[1]);
      view.x -= (event.clientX-last[0])*scale;
      view.y -= (event.clientY-last[1])*scale;
      draw();
    } else if (pointers.size === 2) {
      const [a,b] = [...pointers.values()];
      const distance = Math.hypot(a[0]-b[0],a[1]-b[1]);
      moved += 10;
      if (pinch && distance) zoom(pinch/distance,...toMap((a[0]+b[0])/2,(a[1]+b[1])/2));
      pinch = distance;
    }
  });
  function release(event) {
    const tap = pointers.size === 1 && moved < 8 && event.type === 'pointerup';
    pointers.delete(event.pointerId);
    if (!tap) return;
    const point = toMap(event.clientX,event.clientY);
    const area = base.areas.find((entry)=>contains(entry,point));
    select(area?.id,point);
    options.onPick?.(area ?? null,point);
  }
  svg.addEventListener('pointerup',release);
  svg.addEventListener('pointercancel',release);
  svg.addEventListener('wheel',(event)=>{
    event.preventDefault();
    zoom(event.deltaY > 0 ? 1.25 : .8,...toMap(event.clientX,event.clientY));
  },{ passive:false });
  controls.addEventListener('click',(event)=>{
    const action = event.target.closest('[data-zoom]')?.dataset.zoom;
    if (action === 'in') zoom(.6);
    else if (action === 'out') zoom(1.6);
    else if (action === 'home') { view = { ...full }; draw(); }
  });
  const observer = new ResizeObserver(()=>{ if (root.isConnected) draw(); else observer.disconnect(); });
  observer.observe(svg);

  if (selected) select(selected);
  if (options.home) focus(options.home); else draw();
  return { select:(id)=>{ const area = select(id); if (area) focus(id); return area; },areas:base.areas };
}
